// Configuración de credenciales
const SUPABASE_KEY = 'sb_publishable_dEHZ_X4yFDXpBrblKoSGiw_hKGwva6I';

// Extrae el ID sin importar la estructura de la IA
let rawId = query;
let email = null;

if (typeof query === 'object' && query !== null) {
  rawId = query.p_order_id || query.pedido_id || query.query;
  email = query.p_email || query.email || null;
}

if (!rawId) {
  return "Error: No se proporcionó el ID del pedido.";
}

const cleanId = String(rawId).replace(/\D/g, '');
const orderId = parseInt(cleanId, 10);

if (isNaN(orderId)) {
  return `Error: No se pudo interpretar '${rawId}' como un ID numérico de pedido.`;
}

const payload = { p_order_id: orderId };
if (email) {
  payload.p_email = email;
}

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://nhfxwitnomvtlzcyrfca.supabase.co/rest/v1/rpc/get_order_status',
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json'
    },
    body: payload,
    json: true
  });

  // --- NUEVA VALIDACIÓN ---
  // Si la BD devuelve nulo, indefinido, un arreglo vacío o un error
  if (!response || response.length === 0 || (Array.isArray(response) && response.length === 0) || response.error || Object.keys(response).length === 0) {
      return "RESULTADO: No se encontró ningún pedido con este ID en la base de datos. Dile al cliente amablemente que el número de pedido no existe o es incorrecto, y pídele que lo verifique.";
  }

  return JSON.stringify(response);
} catch (error) {
  return `Error al consultar la base de datos: ${error.message}`;
}
